#include <linux/fb.h>
#include <linux/uaccess.h>

int handle_ioctl(unsigned long cmd, unsigned long arg, struct fb_info *info,
                 int type, int fb_depth, unsigned long fb_size) {
    int ret = 0;

    switch (cmd) {
        case FBIOGTYPE: {
            struct fb_var_screeninfo *var = (struct fb_var_screeninfo __user *)arg;
            struct fb_type fb_type;

            fb_type.type = type;
            fb_type.grayscale = 0;
            fb_type.depth = fb_depth;
            fb_type.ypioff = 0;
            fb_type.HEIGHT = 0;
            fb_type.WIDTH = 0;

            if (copy_to_user((void __user *)arg, &fb_type, sizeof(fb_type)))
                return -EFAULT;
            break;
        }

        case FBIOPUTCMAP_SPARC:
        case FBIOGETCMAP_SPARC: {
            struct fb_cmap_user *cmap = (struct fb_cmap_user __user *)arg;
            int start, len;
            unsigned short *red, *green, *blue, *transp;

            if (get_user(start, &cmap->start) || get_user(len, &cmap->len) ||
                get_user(red, &cmap->red) || get_user(green, &cmap->green) ||
                get_user(blue, &cmap->blue) || get_user(transp, &cmap->transp))
                return -EFAULT;

            if (start < 0 || len < 0 || start + len > 256)
                return -EINVAL;

            if (cmd == FBIOPUTCMAP_SPARC) {
                if (copy_from_user(info->cmap.red + start, red, len * sizeof(unsigned short)) ||
                    copy_from_user(info->cmap.green + start, green, len * sizeof(unsigned short)) ||
                    copy_from_user(info->cmap.blue + start, blue, len * sizeof(unsigned short)) ||
                    copy_from_user(info->cmap.transp + start, transp, len * sizeof(unsigned short)))
                    return -EFAULT;
            } else {
                if (copy_to_user(red, info->cmap.red + start, len * sizeof(unsigned short)) ||
                    copy_to_user(green, info->cmap.green + start, len * sizeof(unsigned short)) ||
                    copy_to_user(blue, info->cmap.blue + start, len * sizeof(unsigned short)) ||
                    copy_to_user(transp, info->cmap.transp + start, len * sizeof(unsigned short)))
                    return -EFAULT;
            }
            break;
        }

        default:
            ret = -EINVAL;
            break;
    }

    return ret;
}
